import { normalizeFixture } from "./normalize.mjs";

const fixturePath = process.argv[2];
if (!fixturePath) {
  process.stderr.write("usage: node cli.mjs <fixture>\n");
  process.exitCode = 2;
} else {
  process.stdout.write(`${JSON.stringify(await normalizeFixture(fixturePath), null, 2)}\n`);
}
